// Every command listed here gets its `allow-*` ACL permission generated by `tauri-plugin`; a
// command missing from the list cannot be granted to any page.
const COMMANDS: &[&str] = &[
    "check_permissions",
    "request_permissions",
    "leave_app",
    "open_app_settings",
    "keep_listening",
    "tts_available",
    "tts_speak",
    "tts_stop",
];

fn main() {
    tauri_plugin::Builder::new(COMMANDS)
        .android_path("android")
        .build();
}
